using System;
using System.Linq;
using UnityEngine;
namespace HarborValeGreybox.Racing {
public sealed partial class RaceProgressStore {
 public int ComponentRemovalFee(string carId,string slot)=>ComponentInventoryLedger.RemovalFee(Profile.fleet,carId,slot);
 public int ComponentFitFee(string partId,string carId)=>ComponentInventoryLedger.FitFee(Profile.fleet,partId,carId);
 public void RemoveComponent(string request,string carId,string slot,int quotedFee)=>ComponentTransaction(request,"component_remove",carId,slot,null,quotedFee);
 public void FitComponent(string request,string partId,string carId,int quotedFee)=>ComponentTransaction(request,"component_fit",carId,null,partId,quotedFee);
 void ComponentTransaction(string request,string kind,string carId,string slot,string partId,int quote){if(!Guid.TryParse(request,out _))throw new ArgumentException("Invalid component request identity");var expectedCar=FleetLedger.Find(Profile.fleet,carId);string expectedEngine=expectedCar.engineId,expectedChoice=slot==null?null:ComponentInventoryLedger.Choice(expectedCar.build,slot);int expectedStage=slot==null?0:ComponentInventoryLedger.Stage(expectedCar.build,slot);using(Lock()){var latest=Load();Profile=latest;foreach(var old in latest.spending)if(old.transactionId==request){if(old.kind!=kind||old.credits!=quote||old.configId!=carId)throw new InvalidOperationException("Component request conflicts with committed receipt");var previous=JsonUtility.FromJson<ComponentMove>(old.fleetJson);if(previous==null||slot!=null&&previous.slot!=slot||partId!=null&&previous.partId!=partId)throw new InvalidOperationException("Component request changed its intended part");return;}ComponentInventoryLedger.Ensure(latest.fleet);var car=ComponentInventoryLedger.OwnedCar(latest.fleet,carId);var engine=ComponentInventoryLedger.Engine(latest.fleet,car);ComponentMove move;int fee;if(kind=="component_remove"){if(car.engineId!=expectedEngine||ComponentInventoryLedger.Stage(car.build,slot)!=expectedStage||ComponentInventoryLedger.Choice(car.build,slot)!=expectedChoice)throw new InvalidOperationException("The fitted component changed. Refresh the garage before removing it.");fee=ComponentInventoryLedger.RemovalFee(latest.fleet,carId,slot);var registered=latest.fleet.parts.SingleOrDefault(p=>p.status=="installed"&&p.installedEngineId==engine.id&&p.slot==slot);move=new ComponentMove{carId=carId,engineId=engine.id,partId=registered?.id??latest.profileId+":component:"+request,modelId=engine.modelId,calibrationId=ComponentInventoryLedger.Calibration(engine.modelId),slot=slot,choice=ComponentInventoryLedger.Choice(car.build,slot),stage=ComponentInventoryLedger.Stage(car.build,slot)};move.offerId=ComponentInventoryLedger.Offer(move.slot,move.choice,move.stage);}else{fee=ComponentInventoryLedger.FitFee(latest.fleet,partId,carId);var part=ComponentInventoryLedger.Find(latest.fleet,partId);move=new ComponentMove{carId=carId,engineId=engine.id,partId=part.id,modelId=part.modelId,calibrationId=part.calibrationId,slot=part.slot,choice=part.choice,stage=part.stage,offerId=part.offerId};}TrafficLedger.CanSpend(latest,fee);if(quote!=fee)throw new InvalidOperationException("Component labor quote changed");if(latest.availableCredits<fee)throw new InvalidOperationException("Not enough credits for component labor");move.fee=fee;var receipt=new TuneReceipt{transactionId=request,prototypeCarId=latest.prototypeCarId,kind=kind,pathId="components_v10",configId=carId,partId=move.partId,stage=0,credits=fee,paidUtc=DateTime.UtcNow.ToString("o"),fleetJson=JsonUtility.ToJson(move)};var candidate=JsonUtility.FromJson<RaceProgress>(JsonUtility.ToJson(latest));candidate.spending.Add(receipt);candidate.availableCredits=checked(candidate.availableCredits-fee);Validate(candidate,true);Write(candidate);Profile=candidate;}}
}
}
